SELECT
    COALESCE(SUM(bet_amount), 0)  AS totalCost,
    COALESCE(SUM(CASE WHEN win_status = 'WIN' THEN win_amount ELSE 0 END), 0) AS totalWin,
    COUNT(*)                       AS totalTickets,
    SUM(CASE WHEN win_status = 'WIN' THEN 1 ELSE 0 END) AS winTickets
FROM t_draw_ticket
WHERE user_id = #{userId}
  AND deleted = 0

      AND mode_id = #{modeId}


      AND DATE(COALESCE(draw_time, bet_time)) >= #{startDate}


      AND DATE(COALESCE(draw_time, bet_time)) <= #{endDate}

SELECT
    DATE_FORMAT(COALESCE(draw_time, bet_time),

               '%Y-%m-%d' 
              '%Y'       
                                  '%Y-%m'    

    ) AS period,
    COALESCE(SUM(bet_amount), 0) AS cost,
    COALESCE(SUM(CASE WHEN win_status = 'WIN' THEN win_amount ELSE 0 END), 0) AS win
FROM t_draw_ticket
WHERE user_id = #{userId}
  AND deleted = 0

      AND mode_id = #{modeId}


      AND DATE(COALESCE(draw_time, bet_time)) >= #{startDate}


      AND DATE(COALESCE(draw_time, bet_time)) <= #{endDate}

GROUP BY period
ORDER BY period ASC

SELECT
    mode_id                        AS modeId,
    COALESCE(SUM(bet_amount), 0)   AS totalCost
FROM t_draw_ticket
WHERE user_id = #{userId}
  AND deleted = 0

      AND DATE(COALESCE(draw_time, bet_time)) >= #{startDate}


      AND DATE(COALESCE(draw_time, bet_time)) <= #{endDate}

GROUP BY mode_id
ORDER BY totalCost DESC
